    logic [31:0] cand_err [0:N_PAIR-1];
    logic        cand_ok  [0:N_PAIR-1];
    logic        sel_valid;
    logic [4:0]  sel_i;
    logic [4:0]  sel_j;
    logic [31:0] sel_err;
    logic [287:0] codeword;

    always_comb begin
        for (int p = 0; p < N_PAIR; p++) begin
            for (int b = 0; b < 32; b++) begin
                cand_err[p][b] = ^(syndrome_in & ERR_MASK[p][b]);
            end
            cand_ok[p] = onehot16(cand_err[p][31:16]) & onehot16(cand_err[p][15:0]);
        end
    end

    always_comb begin
        sel_valid = 1'b0;
        sel_i     = 5'd0;
        sel_j     = 5'd0;
        sel_err   = 32'h0000_0000;
        for (int p = 0; p < N_PAIR; p++) begin
            if (!sel_valid && cand_ok[p]) begin
                sel_valid = 1'b1;
                sel_i     = PAIR_I[p];
                sel_j     = PAIR_J[p];
                sel_err   = cand_err[p];
            end
        end
    end

    always_comb begin
        codeword      = codeword_in;
        decode_result = 1'b1;
        if (syndrome_in == 32'h0000_0000) begin
            decode_result = 1'b0;
        end else if (sel_valid) begin
            codeword[287 - (sel_i*16) -: 16] = codeword_in[287 - (sel_i*16) -: 16] ^ sel_err[31:16];
            codeword[287 - (sel_j*16) -: 16] = codeword_in[287 - (sel_j*16) -: 16] ^ sel_err[15:0];
            decode_result = 1'b0;
        end
    end

    assign data_out = codeword[287:32];

endmodule
